//! 🗂️ Bounded process registry lends each run host's exact immutable compiled parent.
use semio_framework_job::{OriginalTurnFailure,StepContext};
use semio_framework_value::{RetainedCloneProgress,ValueError,ValueRefusalKind};
use semio_plugin_host::{CompiledHandle,GuestRuntimes,GuestRelayNativeOrigin};
use std::{mem::size_of,sync::{Arc,Mutex,OnceLock}};
const CAPACITY:usize=64;
struct Entry{identity:u64,hash:[u8;32],runtime:Arc<GuestRuntimes>,compiled:CompiledHandle,homes:u64,closing:bool}
fn registry()->&'static Mutex<[Option<Entry>;CAPACITY]>{static REGISTRY:OnceLock<Mutex<[Option<Entry>;CAPACITY]>>=OnceLock::new();REGISTRY.get_or_init(||Mutex::new(std::array::from_fn(|_|None)))}
fn refusal()->ValueError{ValueError::literal(ValueRefusalKind::InvariantViolated,"run origin identity or balance differs")}
fn pay(cx:&mut StepContext<'_>,bytes:usize,retirement:bool)->Result<bool,OriginalTurnFailure>{let grant=cx.retained_grant();if (if retirement{cx.retirement_should_yield()}else{cx.should_yield()||cx.is_cancelled()})||grant.maximum_items==0||grant.maximum_copy_bytes<bytes||grant.maximum_depth==0{return Ok(false)}cx.consume_retained(RetainedCloneProgress{copied_items:1,copied_bytes:bytes,..Default::default()})?;cx.consume_fuel(1);Ok(true)}
fn origin(identity:u64,hash:[u8;32])->GuestRelayNativeOrigin{GuestRelayNativeOrigin{cache_identity:identity,package_hash:hash,acquire,resolve,release}}
/// 🌱️ Registers one immutable parent while its run host still retains the same runtime and compiled owner.
pub fn register_step(identity:u64,runtime:&Arc<GuestRuntimes>,compiled:&CompiledHandle,out:&mut Option<GuestRelayNativeOrigin>,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{
 if identity==0{return Err(refusal().into())}if let Some(existing)=out.as_ref(){if existing.cache_identity!=identity||existing.package_hash!=compiled.package_hash||!std::ptr::fn_addr_eq(existing.acquire,acquire as semio_plugin_host::GuestRelayNativeCustody)||!std::ptr::fn_addr_eq(existing.resolve,resolve as semio_plugin_host::GuestRelayNativeResolver)||!std::ptr::fn_addr_eq(existing.release,release as semio_plugin_host::GuestRelayNativeCustody){return Err(refusal().into())}}let Ok(mut slots)=registry().try_lock()else{return Ok(false)};let found=slots.iter().position(|entry|entry.as_ref().is_some_and(|entry|entry.identity==identity&&entry.hash==compiled.package_hash));
 if let Some(index)=found{let entry=slots[index].as_ref().unwrap();if entry.closing||!Arc::ptr_eq(&entry.runtime,runtime)||!entry.compiled.same_origin(compiled){return Err(refusal().into())}if out.is_some(){return Ok(true)}if !pay(cx,size_of::<Option<GuestRelayNativeOrigin>>(),false)?{return Ok(false)}*out=Some(origin(identity,compiled.package_hash));return Ok(true)}
 if out.is_some(){return Err(refusal().into())}let Some(index)=slots.iter().position(Option::is_none)else{return Err(ValueError::literal(ValueRefusalKind::OwnershipLimit,"run origin registry is full").into())};if !pay(cx,size_of::<Entry>()+size_of::<Option<GuestRelayNativeOrigin>>(),false)?{return Ok(false)}slots[index]=Some(Entry{identity,hash:compiled.package_hash,runtime:Arc::clone(runtime),compiled:compiled.clone(),homes:0,closing:false});*out=Some(origin(identity,compiled.package_hash));Ok(true)
}
fn acquire(identity:u64,hash:[u8;32],held:&mut bool,cx:&mut StepContext<'_>)->Result<(),OriginalTurnFailure>{change(identity,hash,held,true,cx)}
fn release(identity:u64,hash:[u8;32],held:&mut bool,cx:&mut StepContext<'_>)->Result<(),OriginalTurnFailure>{change(identity,hash,held,false,cx)}
fn change(identity:u64,hash:[u8;32],held:&mut bool,acquire:bool,cx:&mut StepContext<'_>)->Result<(),OriginalTurnFailure>{if identity==0||*held==acquire{return Err(refusal().into())}let Ok(mut slots)=registry().try_lock()else{return Ok(())};let entry=slots.iter_mut().flatten().find(|entry|entry.identity==identity&&entry.hash==hash).ok_or_else(refusal)?;if acquire&&entry.closing{return Err(refusal().into())}let next=if acquire{entry.homes.checked_add(1)}else{entry.homes.checked_sub(1)}.ok_or_else(refusal)?;if !pay(cx,size_of::<u64>()+size_of::<bool>(),!acquire)?{return Ok(())}entry.homes=next;*held=acquire;Ok(())}
fn resolve(identity:u64,hash:[u8;32],run:&mut dyn FnMut(&GuestRuntimes,&CompiledHandle)->Result<(),OriginalTurnFailure>)->Result<bool,OriginalTurnFailure>{let Ok(slots)=registry().try_lock()else{return Ok(false)};let entry=slots.iter().flatten().find(|entry|entry.identity==identity&&entry.hash==hash).ok_or_else(refusal)?;if entry.homes==0{return Err(refusal().into())}run(&entry.runtime,&entry.compiled)?;Ok(true)}
/// ♻️ Rejects new Homes, waits for every real release, then drops only aliases whose exact originals still remain in the host.
pub fn close_step(identity:u64,runtime:&Arc<GuestRuntimes>,compiled:&CompiledHandle,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{
 let Ok(mut slots)=registry().try_lock()else{return Ok(false)};let Some(index)=slots.iter().position(|entry|entry.as_ref().is_some_and(|entry|entry.identity==identity&&entry.hash==compiled.package_hash))else{return Ok(true)};let entry=slots[index].as_mut().unwrap();if !Arc::ptr_eq(&entry.runtime,runtime)||!entry.compiled.same_origin(compiled){return Err(refusal().into())}if !entry.closing{if !pay(cx,size_of::<bool>(),true)?{return Ok(false)}entry.closing=true;return Ok(false)}if entry.homes!=0{return Ok(false)}if !pay(cx,size_of::<Option<Entry>>(),true)?{return Ok(false)}slots[index].take();Ok(true)
}
